1	#!/usr/bin/env node
2	const fs = require("fs");
3	const path = require("path");
4	const { spawnSync } = require("child_process");
5	
6	const ROOT = process.cwd();
7	const EVALS_DIR = path.join(ROOT, "evals");
8	
9	const KEYWORDS = new Set([
10	  "await", "async", "break", "case", "catch", "class", "const", "continue",
11	  "debugger", "default", "delete", "do", "else", "export", "extends",
12	  "false", "finally", "for", "from", "function", "if", "import", "in", "instanceof",
13	  "let", "new", "null", "of", "return", "static", "super", "switch", "this",
14	  "throw", "try", "typeof", "var", "void", "while", "with", "yield",
15	  "true",
16	]);
17	
18	const KNOWN_GLOBALS = new Set([
19	  "Array", "ArrayBuffer", "BigInt", "Boolean", "DataView", "Date", "Error",
20	  "EvalError", "Event", "Float32Array", "Float64Array", "Infinity", "Intl",
21	  "JSON", "Map", "Math", "NaN", "Number", "Object", "Promise", "Proxy",
22	  "RangeError", "ReferenceError", "Reflect", "RegExp", "Set", "String",
23	  "Symbol", "SyntaxError", "THREE", "TypeError", "URIError", "URL",
24	  "WeakMap", "WeakSet", "alert", "cancelAnimationFrame", "clearInterval",
25	  "clearTimeout", "console", "decodeURIComponent", "document",
26	  "encodeURIComponent", "fetch", "globalThis", "isFinite", "isNaN",
27	  "localStorage", "module", "parseFloat", "parseInt", "performance",
28	  "requestAnimationFrame", "setInterval", "setTimeout", "undefined", "window",
29	]);
