118	function makeScope(parent, kind, file) {
119	  return { parent, kind, file, declarations: new Set(), refs: [], children: [] };
120	}
121	
122	function declare(scope, name) {
123	  if (name && isIdent(name) && !KEYWORDS.has(name)) scope.declarations.add(name);
124	}
125	
126	function nearestFunctionScope(scope) {
127	  let current = scope;
128	  while (current && current.kind !== "function" && current.kind !== "root") {
129	    current = current.parent;
130	  }
131	  return current || scope;
132	}
