134	function parseParamNames(tokens, startIndex) {
135	  const params = [];
136	  const paramIndices = [];
137	  let depth = 0;
138	  for (let i = startIndex; i < tokens.length; i += 1) {
139	    const value = tokens[i].value;
140	    if (value === "(") {
141	      depth += 1;
142	      continue;
143	    }
144	    if (value === ")") {
145	      depth -= 1;
146	      if (depth === 0) return { params, paramIndices, end: i };
147	      continue;
148	    }
149	    if (depth === 1 && isIdent(value) && !KEYWORDS.has(value)) {
150	      params.push(value);
151	      paramIndices.push(i);
152	    }
153	  }
154	  return { params, paramIndices, end: startIndex };
155	}
156	
157	function arrowParamsBefore(tokens, arrowIndex) {
158	  const prev = tokens[arrowIndex - 1];
159	  if (!prev) return [];
160	  if (isIdent(prev.value) && !KEYWORDS.has(prev.value)) return [{ name: prev.value, tokenIndex: arrowIndex - 1 }];
161	  if (prev.value !== ")") return [];
162	  let depth = 0;
163	  for (let i = arrowIndex - 1; i >= 0; i -= 1) {
164	    const value = tokens[i].value;
165	    if (value === ")") depth += 1;
166	    else if (value === "(") {
167	      depth -= 1;
168	      if (depth === 0) {
169	        const params = [];
170	        for (let j = i + 1; j < arrowIndex - 1; j += 1) {
171	          if (isIdent(tokens[j].value) && !KEYWORDS.has(tokens[j].value)) params.push({ name: tokens[j].value, tokenIndex: j });
172	        }
173	        return params;
174	      }
175	    }
176	  }
177	  return [];
178	}
