180	function collectDeclarationsAndRefs(filePath, globalScope, projectGlobals, rootDeclarations) {
181	  const source = fs.readFileSync(filePath, "utf8");
182	  const tokens = tokenize(source);
183	  const fileRoot = makeScope(globalScope, "root", filePath);
184	  globalScope.children.push(fileRoot);
185	  let scope = fileRoot;
186	  const scopeStack = [fileRoot];
187	  let pendingFunctionParams = null;
188	  let pendingFunctionParamEndIndex = -1;
189	  let pendingClassBody = false;
190	  let declarationMode = null;
191	  let declarationDepth = 0;
192	  let declarationExpectName = false;
193	  let skipRefs = new Set();
194	
195	  function pushScope(kind, params) {
196	    const child = makeScope(scope, kind, filePath);
197	    scope.children.push(child);
198	    scopeStack.push(child);
199	    scope = child;
200	    for (const param of params || []) declare(scope, param);
201	  }
202	
203	  function popScope() {
204	    if (scopeStack.length > 1) {
205	      scopeStack.pop();
206	      scope = scopeStack[scopeStack.length - 1];
207	    }
208	  }
209	
210	  for (let i = 0; i < tokens.length; i += 1) {
211	    const token = tokens[i];
212	    const value = token.value;
213	    const prev = tokens[i - 1] && tokens[i - 1].value;
214	    const next = tokens[i + 1] && tokens[i + 1].value;
215	
216	    if (value === "{") {
217	      if (pendingClassBody) {
218	        pushScope("class", []);
219	        pendingClassBody = false;
220	      } else if (pendingFunctionParams && i > pendingFunctionParamEndIndex) {
221	        pushScope("function", pendingFunctionParams);
222	        pendingFunctionParams = null;
223	        pendingFunctionParamEndIndex = -1;
224	      } else {
225	        pushScope("block", []);
226	      }
227	      declarationMode = null;
228	      continue;
229	    }
230	    if (value === "}") {
231	      popScope();
232	      declarationMode = null;
233	      continue;
234	    }
235	
236	    if (value === "function") {
237	      const nameTok = tokens[i + 1];
238	      if (nameTok && isIdent(nameTok.value)) {
239	        declare(scope, nameTok.value);
240	        if (scope.kind === "root") projectGlobals.add(nameTok.value);
241	        skipRefs.add(i + 1);
242	      }
243	      const parenIndex = tokens.findIndex((tok, idx) => idx > i && tok.value === "(");
244	      if (parenIndex !== -1) {
245	        const parsed = parseParamNames(tokens, parenIndex);
246	        pendingFunctionParams = parsed.params;
247	        pendingFunctionParamEndIndex = parsed.end;
248	        for (const idx of parsed.paramIndices) skipRefs.add(idx);
249	      }
250	      continue;
251	    }
252	
253	    if (value === "catch" && next === "(") {
254	      const nameTok = tokens[i + 2];
255	      if (nameTok && isIdent(nameTok.value)) {
256	        pendingFunctionParams = [nameTok.value];
257	        pendingFunctionParamEndIndex = i + 3;
258	        skipRefs.add(i + 2);
259	      }
260	      continue;
261	    }
262	
263	    if (next === "=>") {
264	      skipRefs.add(i);
265	      continue;
266	    }
267	
268	    if (value === "=>") {
269	      const params = arrowParamsBefore(tokens, i);
270	      const paramNames = params.map((param) => param.name);
271	      const paramIndexes = new Set(params.map((param) => tokens[param.tokenIndex].index));
272	      for (const param of params) skipRefs.add(param.tokenIndex);
273	      scope.refs = scope.refs.filter((ref) => !paramIndexes.has(ref.index));
274	      if (next === "{") {
275	        pendingFunctionParams = paramNames;
276	        pendingFunctionParamEndIndex = i;
277	      } else {
278	        for (const param of paramNames) declare(scope, param);
279	      }
280	      continue;
281	    }
282	
283	    if ((value === "var" || value === "let" || value === "const")) {
284	      declarationMode = value;
285	      declarationDepth = 0;
286	      declarationExpectName = true;
287	      continue;
288	    }
289	
290	    if (declarationMode) {
291	      if (value === "(" || value === "[" || value === "{") declarationDepth += 1;
292	      if (value === ")" || value === "]" || value === "}") declarationDepth -= 1;
293	      if ((value === ";" || value === "for") && declarationDepth <= 0) {
294	        declarationMode = null;
295	        declarationExpectName = false;
296	        continue;
297	      }
298	      if (value === "," && declarationDepth === 0) {
299	        declarationExpectName = true;
300	        continue;
301	      }
302	      if (value === "=" && declarationDepth === 0) {
303	        declarationExpectName = false;
304	        continue;
305	      }
306	      if (declarationExpectName && isIdent(value) && !KEYWORDS.has(value) && declarationDepth === 0 && prev !== "." && next !== ":") {
307	        const targetScope = declarationMode === "var" ? nearestFunctionScope(scope) : scope;
308	        declare(targetScope, value);
309	        if (targetScope.kind === "root") {
310	          projectGlobals.add(value);
311	          if (declarationMode === "let" || declarationMode === "const") {
312	            if (!rootDeclarations.has(value)) rootDeclarations.set(value, []);
313	            rootDeclarations.get(value).push({ kind: declarationMode, file: filePath, line: token.line, column: token.column });
314	          }
315	        }
316	        skipRefs.add(i);
317	        declarationExpectName = false;
318	        continue;
319	      }
320	      continue;
321	    }
322	
323	    if (value === "class" && next && isIdent(next)) {
324	      declare(scope, next);
325	      if (scope.kind === "root") {
326	        projectGlobals.add(next);
327	        if (!rootDeclarations.has(next)) rootDeclarations.set(next, []);
328	        rootDeclarations.get(next).push({ kind: "class", file: filePath, line: token.line, column: token.column });
329	      }
330	      skipRefs.add(i + 1);
331	      pendingClassBody = true;
332	      continue;
333	    }
334	
335	    if (scope.kind === "class" && isIdent(value) && next === "(") {
336	      const parsed = parseParamNames(tokens, i + 1);
337	      pendingFunctionParams = parsed.params;
338	      pendingFunctionParamEndIndex = parsed.end;
339	      skipRefs.add(i);
340	      for (const idx of parsed.paramIndices) skipRefs.add(idx);
341	      continue;
342	    }
343	
344	    if (scope.kind === "class" && (value === "get" || value === "set") && tokens[i + 2] && tokens[i + 2].value === "(") {
345	      const parsed = parseParamNames(tokens, i + 2);
346	      pendingFunctionParams = parsed.params;
347	      pendingFunctionParamEndIndex = parsed.end;
348	      skipRefs.add(i);
349	      skipRefs.add(i + 1);
350	      for (const idx of parsed.paramIndices) skipRefs.add(idx);
351	      continue;
352	    }
353	
354	    if ((value === "window" || value === "globalThis" || value === "root") && next === "." && tokens[i + 2] && isIdent(tokens[i + 2].value)) {
355	      const afterProp = tokens[i + 3] && tokens[i + 3].value;
356	      if (afterProp === "=") projectGlobals.add(tokens[i + 2].value);
357	    }
358	
359	    if (!isIdent(value) || KEYWORDS.has(value) || skipRefs.has(i)) continue;
360	    if (prev === ".") continue;
361	    if (next === ":" && prev !== "?") continue;
362	    if (prev === ":" && tokens[i - 2] && tokens[i - 2].value === "?") continue;
363	    scope.refs.push(token);
364	  }
365	}
