386	function jsFilesForEval(evalDir) {
387	  const previewNames = ["index.html", "elevator_sim.html", "elevator_simulation.html", "test.html"];
388	  for (const previewName of previewNames) {
389	    const previewPath = path.join(evalDir, previewName);
390	    if (!fs.existsSync(previewPath)) continue;
391	    const html = fs.readFileSync(previewPath, "utf8");
392	    const scripts = [];
393	    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
394	    let match;
395	    while ((match = scriptRe.exec(html))) {
396	      const src = match[1];
397	      const lower = src.toLowerCase();
398	      if (lower.includes("://") || lower.startsWith("data:") || lower.startsWith("about:")) continue;
399	      if (src.startsWith("/") || src.startsWith("\\")) continue;
400	      const scriptPath = path.resolve(evalDir, src);
401	      if (!scriptPath.startsWith(path.resolve(evalDir))) continue;
402	      if (fs.existsSync(scriptPath) && scriptPath.toLowerCase().endsWith(".js")) {
403	        scripts.push(scriptPath);
404	      }
405	    }
406	    if (scripts.length) return Array.from(new Set(scripts));
407	  }
408	  return fs.readdirSync(evalDir)
409	    .filter((name) => name.toLowerCase().endsWith(".js"))
410	    .filter((name) => !name.toLowerCase().endsWith("_test.js"))
411	    .map((name) => path.join(evalDir, name));
412	}
