function chooseNextActivity(a) {
    if (Clock.simMinute >= a.departureTime) { a.plan = planLeaveBuilding(a); return; }
    for (let i=0;i<a.plannedMeetingTimes.length;i++) {
        if (Clock.simMinute >= a.plannedMeetingTimes[i]) {
            a.plannedMeetingTimes.splice(i,1);
            a.plan = planAttendMeeting(a); return;
        }
    }
    if (Clock.simMinute >= a.lunchTime && !a.hasLunched) { a.plan = planGoToLunch(a); return; }
    const r = Math.random();
    if (r < 0.14) a.plan = planAttendMeeting(a);
    else if (r < 0.26) a.plan = planVisitLounge(a);
    else if (r < 0.41) a.plan = planVisitCoworker(a);
    else a.plan = [{type:'WAIT_SIM', minutes: randInt(18,65)}, {type:'PICK_NEXT_ACTIVITY'}];
}
