const http = require("http");
const fs = require("fs");
const path = require("path");
const { chromium } = require("/Users/jeffgrover/Code/llm-eval/node_modules/playwright");

const DIR = "/Users/jeffgrover/Code/llm-eval/evals/qoder_Qwen3_8-Max-Preview_office_prompt_v3";

function contentType(p) {
