}

async function main() {
  const server = http.createServer((req, res) => {
    const u = decodeURIComponent((req.url || "/").split("?")[0]);
    const f = path.join(DIR, u === "/" ? "index.html" : u);
    if (!f.startsWith(DIR) || !fs.existsSync(f)) { res.writeHead(404); res.end(); return; }
    res.writeHead(200, { "Content-Type": contentType(f) });
    res.end(fs.readFileSync(f));
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const consoleErrors = [];
  const pageErrors = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
  page.on("pageerror", (e) => pageErrors.push(e.message));

  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: "domcontentloaded" });

  const snapshot = () => page.evaluate(() => {
    const sim = window.__sim;
    const out = {
      time: Math.round(sim.clock.simMinute), states: {}, outside: 0, sitting: [],
      nearPairs: 0, elevFloor: sim.elevator.currentFloor, elevState: sim.elevator.state,
      riders: sim.elevator.passengers.size, pending: sim.elevator.pendingBoarders.size,
      calls: sim.elevator.upCalls.size + sim.elevator.downCalls.size, present: 0,
    };
    const movers = [];
    for (const a of sim.agents) {
      out.states[a.state] = (out.states[a.state] || 0) + 1;
      if (a.state !== "DISABLED" && a.state !== "AWAY" && a.state !== "GONE") out.present += 1;
      if (a.group.parent === sim.scene && a.group.position.z > 10.2) out.outside += 1;
      if (a.group.parent && a.group.userData.isSitting) {
        out.sitting.push({
          y: a.group.position.y, floor: a.floor, rot: a.group.rotation.y,
          legL: a.group.userData.leftLeg.rotation.x, state: a.state, role: a.role,
        });
      }
      if (a.group.parent === sim.scene && !a.group.userData.isSitting) movers.push(a.group.position);
    }
    for (let i = 0; i < movers.length; i += 1) {
      for (let j = i + 1; j < movers.length; j += 1) {
        if (Math.abs(movers[i].y - movers[j].y) > 1) continue;
        const d = Math.hypot(movers[i].x - movers[j].x, movers[i].z - movers[j].z);
        if (d < 0.25) out.nearPairs += 1;
      }
    }
    return out;
  });

  const fmt = (s) => {
    const h = Math.floor(s.time / 60); const m = s.time % 60;
    const st = Object.entries(s.states).filter((kv) => !["DISABLED", "AWAY", "GONE"].includes(kv[0]))
      .map((kv) => kv[0] + "=" + kv[1]).join(" ");
    return `${h}:${String(m).padStart(2, "0")} present=${s.present} elev=${s.elevFloor}[${s.elevState}] riders=${s.riders} pend=${s.pending} calls=${s.calls} outside=${s.outside} near=${s.nearPairs} sit=${s.sitting.length} :: ${st}`;
  };

  const snaps = [];
  await page.waitForTimeout(2000); snaps.push(await snapshot());
  await page.waitForTimeout(10000); snaps.push(await snapshot());
  await page.waitForTimeout(15000); snaps.push(await snapshot());

  // Boost to 600x via the real slider.
  await page.evaluate(() => {
    const sliders = Array.from(document.querySelectorAll("input[type='range']"));
    const speed = sliders[0];
    speed.value = speed.max;
    speed.dispatchEvent(new Event("input", { bubbles: true }));
  });
  for (let i = 0; i < 4; i += 1) {
    await page.waitForTimeout(5000);
    snaps.push(await snapshot());
  }

  for (const s of snaps) console.log(fmt(s));

