  if (Math.max(...atDesk) < 5) problems.push("fewer than 5 workers ever reached AT_DESK: " + atDesk.join(","));

  const transitSeen = snaps.some((s) => (s.states.IN_CAR || 0) + (s.states.WAITING_ELEVATOR || 0) > 0);
  if (!transitSeen) problems.push("never observed IN_CAR/WAITING_ELEVATOR agents");
  if (snaps.every((s) => s.riders === 0)) problems.push("elevator never carried riders");

