  }
  const last = snaps[snaps.length - 1];
  if (last.nearPairs > 2) problems.push(`bunching at end: ${last.nearPairs} near-overlapping pairs`);

  let sitChecked = 0;
  for (const s of snaps) {
    for (const sit of s.sitting) {
      sitChecked += 1;
      if (Math.abs(sit.legL + Math.PI / 2) > 0.02) problems.push(`sitting legs not bent (leg=${sit.legL.toFixed(2)}) state=${sit.state}`);
      const expectY = sit.floor * 3.4 - 0.35;
      if (Math.abs(sit.y - expectY) > 0.06) problems.push(`sitting height wrong: y=${sit.y.toFixed(2)} expect=${expectY.toFixed(2)} floor=${sit.floor}`);
      if (sit.state === "AT_DESK" && Math.abs(Math.abs(sit.rot) - Math.PI) > 0.05) {
        problems.push(`desk worker facing wrong way: rot=${sit.rot.toFixed(2)} (expect ~PI, toward monitor)`);
      }
      if (sit.state === "IN_MEETING" && ![0, Math.PI, Math.PI / 2, -Math.PI / 2].some((f) => Math.abs(sit.rot - f) < 0.05)) {
        problems.push(`meeting sitter odd facing rot=${sit.rot.toFixed(2)}`);
      }
    }
  }
  if (sitChecked === 0) problems.push("never observed a sitting agent");

  const floorsSeen = new Set(snaps.map((s) => s.elevFloor));
  if (floorsSeen.size < 2) problems.push("elevator never changed floor");

  console.log("\nsitting samples checked: " + sitChecked);
  console.log("elevator floors seen: " + Array.from(floorsSeen).sort().join(","));
  if (problems.length) {
    console.log("\nPROBLEMS (" + problems.length + "):");
    for (const p of new Set(problems)) console.log("  - " + p);
    process.exitCode = 1;
  } else {
    console.log("\nBEHAVIOR PROBE: all checks passed");
  }

  await browser.close();
