if (data.phase === "walkToSpot") {
    const step = WALK_SPEED * dt;
    const dx = data.spot.x - pos.x;
    const dz = data.spot.z - pos.z;
    const dist = Math.hypot(dx, dz);
    if (dist > 0.000001) {
        const use = Math.min(step, dist);
        pos.x += dx / dist * use;
